sd:section.arch:state-shape:
GameSession { schemaVersion: number, puzzleId: string, // cache key; equality uses givens bytes dim: 9, givens: Uint8Array(81), values: Uint8Array(81), candidates: Uint16Array(81), cellNotes: Record<number, string>, regionNotes: Record<"r0".."r8" | "c0".."c8" | "b0".."b8", string>, createdAt: number, updatedAt: number }
UiState { selection: number | null, activeDigit: number | null, candidateHeld: boolean, candidateSticky: boolean, editor: null | { targetKind, targetKey, draft, dirty }, dialog: null | { kind, payload }, notesOpen: boolean, boardScale: number }
Settings { schemaVersion: number, autoRemoveCandidates: boolean, // true showConflicts: boolean, // true shiftQuasimode: boolean, // true touchControls: "auto" | "show" | "hide", hintStripSeenCount: number }
HistoryEntry { kind: "value" | "candidates" | "cellNote" | "regionNote", key: number | string, before: number | string, after: number | string, groupId: number, at: number }
